 1	/**
 2	 * GUI API Route Handlers
 3	 *
 4	 * Pure async functions — one per REST endpoint. Each handler accepts parsed
 5	 * request parameters and returns a result object (or throws a structured error).
 6	 * The HTTP server (gui/server.ts) calls these handlers and maps results to HTTP
 7	 * responses.
 8	 *
 9	 * Error shape:  { code: string, message: string, details?: unknown }
10	 *   NOT_FOUND        → 404
11	 *   FORBIDDEN        → 403
12	 *   VALIDATION_ERROR → 400
13	 *   (unhandled)      → 500
14	 *
15	 * STDIO discipline: this file never writes to process.stdout.
16	 */
17	
18	import { rm, readFile, readdir } from 'node:fs/promises';
19	import { join, resolve, sep } from 'node:path';
20	import { z } from 'zod';
21	import { LedgerStore, SlugConflictError } from '../src/storage/ledger-store.js';
22	import { withLock } from '../src/storage/file-lock.js';
23	import { inferProjectRootFromPlanPath, resolveProjectDir } from '../src/utils/ledger-root.js';
24	import { assertSafeSegment } from '../src/utils/path-validator.js';
25	import { readProjectName } from '../src/utils/read-project-name.js';
26	import { PLAN_ARCHIVE_FILENAME, SYNTHESIS_ARCHIVE_FILENAME, DIALOGUES_DIR, CHUNKS_DIR } from '../src/utils/constants.js';
27	import {
28	  PIPELINE_AGENT_MAP,
29	  DEFAULT_PIPELINE_STAGES,
30	  CANONICAL_PIPELINE_ORDERING,
31	} from '../src/utils/pipeline-maps.js';
32	import type { PipelineType } from '../src/utils/pipeline-maps.js';
33	import { ProjectMetaSchema } from '../src/schema/project-meta.js';
34	import type { ProjectMeta } from '../src/schema/project-meta.js';
35	import type { ProjectStatus, WorkPackageStatus } from '../src/schema/enums.js';
36	import type { RootIndex } from '../src/schema/root-index.js';
37	import type { IncidentContext, WorkPackageDetail } from '../src/schema/work-package.js';
38	
39	/**
40	 * Extended WP detail response that includes the server's canonical default pipeline stages.
41	 * The extra field is additive — all existing fields of WorkPackageDetail are preserved.
42	 */
43	export type WorkPackageDetailResponse = WorkPackageDetail & {
44	  default_pipeline_stages: string[];
45	};
46	import { getConfig, writeConfig, GuiConfigPartialSchema } from '../src/gui/config.js';
47	import type { GuiConfig } from '../src/gui/config.js';
48	import {
49	  analyzeProjectForReset,
50	  applyProjectReset,
51	  getPassedStages,
52	  markProjectComplete,
53	} from '../src/utils/project-reset.js';
54	import type {
55	  WpDecision,
56	  ProjectResetDiagnosis,
57	  ProjectResetResult,
58	  MarkProjectCompleteResult,
59	} from '../src/utils/project-reset.js';
60	import { ApiError } from '../src/gui/errors.js';
61	export { ApiError };
62	import {
63	  getQueue,
64	  killQueueEntry,
65	  dismissQueueEntry,
66	  startOrchestrator,
67	  getRunStatus,
68	} from './orchestrator-manager.js';
69	import type { QueueEntry, KillResult, StartResult, RunStatus } from './orchestrator-manager.js';
70	import { KnowledgeStoreManager } from '../src/storage/knowledge-store.js';
71	import { InsightScope, InsightSchema, PROJECT_SLUG_REGEX } from '../src/schema/knowledge.js';
72	import type { Insight } from '../src/schema/knowledge.js';
73	
74	// ---------------------------------------------------------------------------
75	// Internal helpers
76	// ---------------------------------------------------------------------------
77	
78	function notFound(message: string): never {
79	  throw new ApiError('NOT_FOUND', message);
80	}
81	
82	function forbidden(message: string): never {
83	  throw new ApiError('FORBIDDEN', message);
84	}
85	
86	function conflict(message: string): never {
87	  throw new ApiError('CONFLICT', message);
88	}
89	
90	function validationError(message: string, details?: unknown): never {
91	  throw new ApiError('VALIDATION_ERROR', message, details);
92	}
93	
94	/**
95	 * Allowlist for WP IDs and queue entry IDs: must start with alnum, then word chars or hyphens.
96	 * Note: `\w` includes underscore intentionally — WP IDs (`WP-001`) and queue entry IDs may
97	 * contain underscores in future formats. This is permissive by design.
98	 */
99	const SAFE_ID_PATTERN = /^[A-Za-z0-9][\w-]*$/;

100	
101	/**
102	 * Guards against path-traversal attacks on the project slug URL parameter.
103	 *
104	 * Rejects any slug that does not satisfy the safe-slug rules
105	 * (lowercase alphanumeric + hyphens, must start with an alphanumeric character).
106	 * This reuses the same slug format enforced on project creation and rename,
107	 * ensuring only lowercase alphanumeric characters and hyphens are accepted —
108	 * eliminating path separators and traversal sequences by design.
109	 *
110	 * @param slug - The raw slug string extracted from the request URL.
111	 */
112	function assertSafeSlug(slug: string): void {
113	  if (!assertSafeSegment(slug)) {
114	    notFound(`Invalid project slug: '${slug}'.`);
115	  }
116	}
117	
118	/**
119	 * Guards against path-traversal attacks on the work-package ID URL parameter.
120	 *
121	 * Rejects any wpId that does not match {@link SAFE_ID_PATTERN}
122	 * (`/^[A-Za-z0-9][\w-]*$/`). Requires an alphanumeric first character,
123	 * blocking `..`, `.`, and all path separators by design.
124	 *
125	 * @param wpId - The raw work-package ID string extracted from the request URL.
126	 */
127	function assertSafeWpId(wpId: string): void {
128	  if (!wpId || !SAFE_ID_PATTERN.test(wpId)) {
129	    notFound(`Invalid work-package ID: '${wpId}'.`);
130	  }
131	}
132	
133	/**
134	 * Guards against path-traversal attacks on the orchestrator queue entry ID
135	 * URL parameter.
136	 *
137	 * Rejects any id that does not match {@link SAFE_ID_PATTERN}
138	 * (`/^[A-Za-z0-9][\w-]*$/`). Requires an alphanumeric first character,
139	 * blocking `..`, `.`, and all path separators by design.
140	 *
141	 * @param id - The raw queue entry ID string extracted from the request URL.
142	 */
143	function assertSafeQueueId(id: string): void {
144	  if (!id || !SAFE_ID_PATTERN.test(id)) {
145	    notFound(`Invalid queue entry ID: '${id}'.`);
146	  }
147	}
148	
149	/**
150	 * Resolves a LedgerStore for URL-parameter-driven handlers.
151	 *
152	 * Locates the namespaced storage directory via resolveProjectDir(), reads
153	 * .meta.json for plan_path, and constructs a LedgerStore from it. Callers
154	 * must validate `slug` (via assertSafeSlug) before calling. If `repoName` is
155	 * provided, it is validated here via assertSafeSlug before being joined with
156	 * `slug` to form a qualified `{repo}/{slug}` lookup.
157	 *
158	 * @remarks **Security contract — AMBIGUOUS → NOT_FOUND downgrade:**
159	 * When `resolveProjectDir()` throws an AMBIGUOUS error (multiple repos contain
160	 * this slug), this function intentionally downgrades it to the same NOT_FOUND
161	 * ApiError used for a missing project. This prevents callers from learning
162	 * that a slug exists in any repository (cross-namespace existence leak).
163	 * The inline comment in the catch block documents the downgrade decision;
164	 * do not restore the original AMBIGUOUS message without a security review.
165	 *
166	 * @throws ApiError NOT_FOUND when the project cannot be located, is ambiguous
167	 *   across namespaces, or has no metadata.
168	 */
169	async function resolveProjectStore(
170	  ledgerRoot: string,
171	  slug: string,
172	  repoName?: string
173	): Promise<LedgerStore> {
174	  if (repoName !== undefined) {
175	    assertSafeSlug(repoName);
176	  }
177	  const slugOrQualified = repoName !== undefined ? `${repoName}/${slug}` : slug;
178	
179	  let storageDir: string;
180	  try {
181	    storageDir = await resolveProjectDir(slugOrQualified, ledgerRoot);
182	  } catch (err) {
183	    const msg = err instanceof Error ? err.message : String(err);
184	    // Intentionally downgrade AMBIGUOUS to NOT_FOUND: the caller must not learn
185	    // that multiple repos contain this slug (prevents cross-namespace existence leak).
186	    if (msg.startsWith('NOT_FOUND') || msg.startsWith('AMBIGUOUS')) {
187	      notFound(`Project '${slug}' not found.`);
188	    }
189	    throw err;
190	  }
191	
192	  try {
193	    const raw = await readFile(join(storageDir, '.meta.json'), 'utf-8');
194	    const meta = ProjectMetaSchema.parse(JSON.parse(raw));
195	    return new LedgerStore(meta.plan_path, ledgerRoot);
196	  } catch {
197	    notFound(`Project '${slug}' not found or has no metadata.`);
198	  }
199	}
200	
201	// ---------------------------------------------------------------------------
202	// GET /api/insights
203	// ---------------------------------------------------------------------------
204	
205	export interface InsightEntry {
206	  project_slug: string;
207	  project_status: ProjectStatus;
208	  type: string;
209	  priority: 'low' | 'medium' | 'high';
210	  timestamp: string;
211	  agent: string;
212	  note: string;
213	  context?: IncidentContext;
214	}
215	
216	/**
217	 * Aggregates all project_comments from every project ledger into a single
218	 * flat array, sorted by timestamp descending (newest first).
219	 * Per-project read failures are logged to stderr and skipped gracefully.
220	 * Returns an empty array when no projects exist or no comments are found.
221	 */
222	export async function handleGetInsights(ledgerRoot: string): Promise<InsightEntry[]> {
223	  const projects = await LedgerStore.listAllProjects(ledgerRoot);
224	
225	  const entries: InsightEntry[] = [];
226	
227	  await Promise.all(
228	    projects.map(async (meta) => {
229	      const store = new LedgerStore(meta.plan_path, ledgerRoot);
230	      let rootIndex;
231	      try {
232	        rootIndex = await store.readRootIndex();
233	      } catch (err) {
234	        process.stderr.write(
235	          `[handleGetInsights] Skipping project "${meta.slug}": ${String(err)}\n`
236	        );
237	        return;
238	      }
239	
240	      const comments = rootIndex.project_comments;
241	      if (!comments || comments.length === 0) return;
242	
243	      for (const comment of comments) {
244	        entries.push({
245	          project_slug: meta.slug,
246	          project_status: meta.status,
247	          ...comment,
248	        });
249	      }
250	    })
251	  );
252	
253	  // Sort by timestamp descending (newest first)
254	  entries.sort((a, b) => b.timestamp.localeCompare(a.timestamp));
255	
256	  return entries;
257	}
258	
259	// ---------------------------------------------------------------------------
260	// GET /api/projects
261	// ---------------------------------------------------------------------------
262	
263	export interface ProjectSummary extends ProjectMeta {
264	  total_work_packages: number;
265	  pending_work_packages: number;
266	  progress_pct: number;
267	  project_name: string | null;
268	  repository_name: string | null;
269	}
270	
271	/** Fields that the project list can be sorted by. */
272	export type ProjectSortField =
273	  | 'project'
274	  | 'repository'
275	  | 'status'
276	  | 'total_work_packages'
277	  | 'done'
278	  | 'date_created'
279	  | 'last_updated'
280	  | 'runner';
281	
282	/** Raw query parameters accepted by GET /api/projects. */
283	export interface ProjectListParams {
284	  page?: number | string;
285	  limit?: number | string;
286	  /** 'ACTIVE' (default), 'ALL', or a specific ProjectStatus value. */
287	  status?: string;
288	  /** Case-insensitive substring match on slug, project_name, repository_name. */
289	  search?: string;
290	  /** Sort column. Defaults to 'last_updated'. */
291	  sort?: string;
292	  /** 'asc' or 'desc'. Defaults to 'desc'. */
293	  dir?: string;
294	  /** Normalized runner filter ('orchestrator', 'vscode', 'claude-code', 'unknown'). Unrecognized values return empty results without a 500. */
295	  runner?: string;
296	}
297	
298	/** Paginated response envelope returned by handleListProjects. */
299	export interface ProjectListEnvelope {

300	  projects: ProjectSummary[];
301	  total: number;
302	  page: number;
303	  limit: number;
304	  total_pages: number;
305	  /** Per-status counts computed from the search-filtered set (before status filter). */
306	  status_counts: Record<string, number>;
307	  /** Per-runner counts computed from the search-filtered set (before runner filter). 'unknown' for projects without a stored runner field. */
308	  runner_counts: Record<string, number>;
309	}
310	
311	const SORT_FIELDS = new Set<ProjectSortField>([
312	  'project',
313	  'repository',
314	  'status',
315	  'total_work_packages',
316	  'done',
317	  'date_created',
318	  'last_updated',
319	  'runner',
320	]);
321	
322	const VALID_STATUS_FILTERS = new Set([
323	  'ACTIVE', 'ALL', 'READY', 'IN_PROGRESS', 'COMPLETE', 'BLOCKED', 'ARCHIVED', 'CANCELLED',
324	]);
325	
326	/**
327	 * Returns a paginated envelope of enriched project summaries.
328	 *
329	 * Processing pipeline:
330	 *  1. Enrich all projects (cache fast-path from .meta.json when available).
331	 *  2. Apply search filter to the full list.
332	 *  3. Compute status_counts from the search-filtered set (before status filter).
333	 *  4. Apply status filter.
334	 *  5. Sort.
335	 *  6. Paginate (slice) and return the envelope.
336	 *
337	 * project_name resolution order: manifest file → slug date-strip fallback →
338	 * meta.title (takes precedence when set).
339	 * Per-project read failures are isolated so one bad project never breaks
340	 * the entire response.
341	 */
342	export async function handleListProjects(
343	  ledgerRoot: string,
344	  rawParams: ProjectListParams = {}
345	): Promise<ProjectListEnvelope> {
346	  // --- Validate and sanitise params ---
347	  const page = Math.max(1, Math.floor(Number(rawParams.page) || 1));
348	  const limitRaw = rawParams.limit !== undefined ? Math.floor(Number(rawParams.limit)) : 50;
349	  const limit = Math.min(200, Math.max(1, isNaN(limitRaw) ? 50 : limitRaw));
350	  const statusFilter =
351	    rawParams.status !== undefined && VALID_STATUS_FILTERS.has(rawParams.status)
352	      ? rawParams.status
353	      : 'ACTIVE';
354	  const search = (rawParams.search ?? '').trim();
355	  const sortRaw = rawParams.sort ?? '';
356	  const sort: ProjectSortField = SORT_FIELDS.has(sortRaw as ProjectSortField)
357	    ? (sortRaw as ProjectSortField)
358	    : 'last_updated';
359	  const dir: 'asc' | 'desc' = rawParams.dir === 'asc' ? 'asc' : 'desc';
360	  // runner filter — undefined means no filter; any string value (including unrecognized ones) is accepted
361	  // so that unrecognized runners return an empty set rather than a 500 error.
362	  const runnerFilter: string | undefined = rawParams.runner;
363	
364	  const allProjects = await LedgerStore.listAllProjects(ledgerRoot);
365	
366	  // --- Enrich all projects ---
367	  const enrichedAll = await Promise.all(
368	    allProjects.map(async (meta): Promise<ProjectSummary> => {
369	      let total_work_packages = 0;
370	      let pending_work_packages = 0;
371	      let progress_pct = 0;
372	      let project_name: string | null = null;
373	
374	      const projectRoot = inferProjectRootFromPlanPath(meta.plan_path);
375	
376	      // Derive project name from slug first — takes precedence over any repo
377	      // manifest file (package.json etc.), which would return the repository
378	      // name rather than the individual plan's name. Strips the YYYY-MM-DD-
379	      // date prefix and title-cases the remainder, e.g.
380	      // "2026-02-27-gui-enhancements" → "Gui Enhancements".
381	      const slugMatch = meta.slug.match(/^\d{4}-\d{2}-\d{2}-(.+)$/);
382	      if (slugMatch) {
383	        project_name = slugMatch[1]
384	          .split('-')
385	          .map((w) => (w.length > 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w))
386	          .join(' ');
387	      }
388	
389	      // FAST PATH: use cached enrichment values from .meta.json when available.
390	      // Falls back to I/O-based enrichment for legacy meta files that pre-date
391	      // the enrichment cache (WP-006). The cached project_name is only used
392	      // when slug derivation produced no name (non-date-prefixed slugs).
393	      if (
394	        meta.total_work_packages !== undefined &&
395	        meta.project_name !== undefined
396	      ) {
397	        total_work_packages = meta.total_work_packages;
398	        pending_work_packages = meta.pending_work_packages ?? 0;
399	        progress_pct = meta.progress_pct ?? (total_work_packages > 0
400	          ? Math.round(((total_work_packages - pending_work_packages) / total_work_packages) * 100)
401	          : 0);
402	        if (project_name === null) {
403	          project_name = meta.project_name;
404	        }
405	      } else {
406	        const store = new LedgerStore(meta.plan_path, ledgerRoot);
407	
408	        await Promise.all([
409	          (async () => {
410	            try {
411	              const rootIndex = await store.readRootIndex();
412	              total_work_packages = rootIndex.total_work_packages ?? 0;
413	              pending_work_packages = rootIndex.pending_work_packages ?? 0;
414	              progress_pct = total_work_packages > 0
415	                ? Math.round(((total_work_packages - pending_work_packages) / total_work_packages) * 100)
416	                : 0;
417	            } catch {
418	              // default to 0
419	            }
420	          })(),
421	          (async () => {
422	            // Only read the repo manifest when slug derivation produced no name.
423	            if (project_name === null) {
424	              project_name = await readProjectName(projectRoot);
425	            }
426	          })(),
427	        ]);
428	      }
429	
430	      // Persisted title takes precedence over all auto-detected names.
431	      if (meta.title && meta.title.trim().length > 0) {
432	        project_name = meta.title;
433	      }
434	
435	      // Derive repository_name from the project root directory name.
436	      const repository_name = projectRoot
437	        ? (projectRoot.split(/[\\/]/).filter(Boolean).pop() ?? null)
438	        : null;
439	
440	      return {
441	        ...meta,
442	        // Normalize runner: projects without a stored runner field default to 'unknown'
443	        // for consistent filtering and display.
444	        runner: meta.runner ?? 'unknown',
445	        total_work_packages,
446	        pending_work_packages,
447	        progress_pct,
448	        project_name,
449	        repository_name,
450	      };
451	    })
452	  );
453	
454	  // --- Step 2: Search filter (applied to full list, before status filter) ---
455	  const searchLower = search.toLowerCase();
456	  const searchFiltered = searchLower
457	    ? enrichedAll.filter(
458	        (p) =>
459	          p.slug.toLowerCase().includes(searchLower) ||
460	          (p.project_name ?? '').toLowerCase().includes(searchLower) ||
461	          (p.repository_name ?? '').toLowerCase().includes(searchLower)
462	      )
463	    : enrichedAll;
464	
465	  // --- Step 3: Compute status_counts and runner_counts from search-filtered set (before status/runner filter) ---
466	  const status_counts: Record<string, number> = {};
467	  const runner_counts: Record<string, number> = {};
468	  for (const p of searchFiltered) {
469	    status_counts[p.status] = (status_counts[p.status] ?? 0) + 1;
470	    const r = p.runner ?? 'unknown';
471	    runner_counts[r] = (runner_counts[r] ?? 0) + 1;
472	  }
473	
474	  // --- Step 4a: Status filter ---
475	  const statusFiltered =
476	    statusFilter === 'ALL'
477	      ? searchFiltered
478	      : statusFilter === 'ACTIVE'
479	        ? searchFiltered.filter((p) => p.status !== 'ARCHIVED')
480	        : searchFiltered.filter((p) => p.status === statusFilter);
481	
482	  // --- Step 4b: Runner filter (applied after status filter; unrecognized values return empty set) ---
483	  const filtered =
484	    runnerFilter !== undefined
485	      ? statusFiltered.filter((p) => (p.runner ?? 'unknown') === runnerFilter)
486	      : statusFiltered;
487	
488	  // --- Step 5: Sort ---
489	  const sorted = [...filtered].sort((a, b) => {
490	    let aVal: string | number;
491	    let bVal: string | number;
492	    switch (sort) {
493	      case 'project':
494	        aVal = (a.project_name ?? a.slug).toLowerCase();
495	        bVal = (b.project_name ?? b.slug).toLowerCase();
496	        break;
497	      case 'repository':
498	        aVal = (a.repository_name ?? '').toLowerCase();
499	        bVal = (b.repository_name ?? '').toLowerCase();

500	        break;
501	      case 'status':
502	        aVal = a.status;
503	        bVal = b.status;
504	        break;
505	      case 'total_work_packages':
506	        aVal = a.total_work_packages;
507	        bVal = b.total_work_packages;
508	        break;
509	      case 'done':
510	        aVal = a.progress_pct;
511	        bVal = b.progress_pct;
512	        break;
513	      case 'date_created':
514	        aVal = a.date_created ?? '';
515	        bVal = b.date_created ?? '';
516	        break;
517	      case 'runner':
518	        aVal = (a.runner ?? 'unknown').toLowerCase();
519	        bVal = (b.runner ?? 'unknown').toLowerCase();
520	        break;
521	      case 'last_updated':
522	      default:
523	        aVal = a.last_updated ?? '';
524	        bVal = b.last_updated ?? '';
525	        break;
526	    }
527	    if (aVal < bVal) return dir === 'asc' ? -1 : 1;
528	    if (aVal > bVal) return dir === 'asc' ? 1 : -1;
529	    return 0;
530	  });
531	
532	  // --- Step 6: Paginate ---
533	  const total = sorted.length;
534	  const total_pages = Math.max(1, Math.ceil(total / limit));
535	  const start = (page - 1) * limit;
536	  const pageSlice = sorted.slice(start, start + limit);
537	
538	  return {
539	    projects: pageSlice,
540	    total,
541	    page,
542	    limit,
543	    total_pages,
544	    status_counts,
545	    runner_counts,
546	  };
547	}
