552	
553	export type ProjectDetail = RootIndex & {
554	  meta: ProjectMeta;
555	  project_name: string | null;
556	  timing?: {
557	    project_elapsed_ms: number | null;
558	    total_active_ms: number;
559	    pipeline_runs: number;
560	  };
561	};
562	
563	/**
564	 * Returns the combined root index + meta for a project.
565	 * Throws NOT_FOUND if the project slug does not exist in the ledger.
566	 * project_name resolution order: manifest file → slug date-strip fallback →
567	 * meta.title (takes precedence when set).
568	 * @param repoName  Optional repository name used to resolve the namespaced storage path.
569	 */
570	export async function handleGetProject(
571	  ledgerRoot: string,
572	  slug: string,
573	  repoName?: string
574	): Promise<ProjectDetail> {
575	  assertSafeSlug(slug);
576	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
577	
578	  try {
579	    const [rootIndex, meta] = await Promise.all([
580	      store.readRootIndex(),
581	      store.readProjectMeta(),
582	    ]);
583	
584	    // Resolve project_name using the same logic as handleListProjects:
585	    // slug derivation first, repo manifest only as a last resort.
586	    let project_name: string | null = null;
587	
588	    const slugMatch = slug.match(/^\d{4}-\d{2}-\d{2}-(.+)$/);
589	    if (slugMatch) {
590	      project_name = slugMatch[1]
591	        .split('-')
592	        .map((w) => (w.length > 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w))
593	        .join(' ');
594	    }
595	
596	    if (project_name === null) {
597	      const projectRoot = inferProjectRootFromPlanPath(meta.plan_path);
598	      project_name = await readProjectName(projectRoot);
599	    }
600	
601	    if (meta.title && meta.title.trim().length > 0) {
602	      project_name = meta.title;
603	    }
604	
605	    // Compute timing: sum duration_ms across all WP pipelines
606	    const wpDetails = (
607	      await Promise.all(
608	        rootIndex.work_packages.map(async (wpSummary) => {
609	          try {
610	            return await store.readWorkPackage(wpSummary.work_package_id);
611	          } catch {
612	            return null;
613	          }
614	        })
615	      )
616	    ).filter((wp): wp is WorkPackageDetail => wp !== null);
617	
618	    let total_active_ms = 0;
619	    let pipeline_runs = 0;
620	    for (const wp of wpDetails) {
621	      for (const p of wp.pipelines) {
622	        if (p.duration_ms != null) {
623	          total_active_ms += p.duration_ms;
624	          pipeline_runs++;
625	        }
626	      }
627	    }
628	    const createdAt = meta.date_created ? new Date(meta.date_created).getTime() : NaN;
629	    const updatedAt = meta.last_updated ? new Date(meta.last_updated).getTime() : NaN;
630	    const project_elapsed_ms = (!isNaN(createdAt) && !isNaN(updatedAt)) ? updatedAt - createdAt : null;
631	
632	    const timing = { project_elapsed_ms, total_active_ms, pipeline_runs };
633	    return { ...rootIndex, meta, project_name, timing };
634	  } catch (err) {
635	    if (err instanceof ApiError) throw err;
636	    notFound(`Project '${slug}' not found or corrupted: ${String(err)}`);
637	  }
638	}
