 951	/**
 952	 * Zod schema for the reset request body.
 953	 */
 954	const WpDecisionSchema = z.object({
 955	  action: z.enum(['reset', 'skip', 'cancel']),
 956	  reset_criteria: z.boolean().optional(),
 957	});
 958	
 959	const ResetRequestSchema = z.object({
 960	  dry_run: z.boolean(),
 961	  decisions: z.record(z.string(), WpDecisionSchema).optional(),
 962	});
 963	
 964	/**
 965	 * Handles project reset: analyze (dry_run=true) or apply (dry_run=false).
 966	 *
 967	 * - dry_run=true: Returns diagnosis with per-WP analysis and suggested actions.
 968	 * - dry_run=false: Requires `decisions` map. Applies per-WP reset/skip/cancel.
 969	 *
 970	 * Throws NOT_FOUND if the project does not exist.
 971	 * Throws VALIDATION_ERROR if the request body is invalid.
 972	 * @param repoName  Optional repository name used to resolve the namespaced storage path.
 973	 */
 974	export async function handleResetProject(
 975	  ledgerRoot: string,
 976	  slug: string,
 977	  body: unknown,
 978	  repoName?: string
 979	): Promise<ProjectResetDiagnosis | ProjectResetResult> {
 980	  assertSafeSlug(slug);
 981	
 982	  // Validate body
 983	  const parseResult = ResetRequestSchema.safeParse(body);
 984	  if (!parseResult.success) {
 985	    validationError('Invalid reset request body.', parseResult.error.issues);
 986	  }
 987	  const { dry_run, decisions } = parseResult.data;
 988	
 989	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
 990	
 991	  // Read root index and all WP details
 992	  let rootIndex: RootIndex;
 993	  try {
 994	    rootIndex = await store.readRootIndex();
 995	  } catch (err) {
 996	    notFound(`Project '${slug}' not found or corrupted: ${String(err)}`);
 997	  }
 998	
 999	  const wpDetails: WorkPackageDetail[] = [];
1000	  for (const wpSummary of rootIndex.work_packages) {
1001	    try {
1002	      const wp = await store.readWorkPackage(wpSummary.work_package_id);
1003	      wpDetails.push(wp);
1004	    } catch (err) {
1005	      process.stderr.write(
1006	        `[handleResetProject] Skipping WP "${wpSummary.work_package_id}": ${String(err)}\n`
1007	      );
1008	    }
1009	  }
1010	
1011	  // Analyze
1012	  const diagnosis = analyzeProjectForReset(slug, rootIndex, wpDetails);
1013	
1014	  if (dry_run) {
1015	    return diagnosis;
1016	  }
1017	
1018	  // Apply mode — decisions are required
1019	  if (!decisions || Object.keys(decisions).length === 0) {
1020	    validationError('Decisions map is required when dry_run is false.');
1021	  }
1022	
1023	  const result = await applyProjectReset(store, diagnosis, decisions as Record<string, WpDecision>);
1024	  return result;
1025	}
