1027	// ---------------------------------------------------------------------------
1028	// PATCH /api/projects/:slug
1029	// ---------------------------------------------------------------------------
1030	
1031	/**
1032	 * Zod schema for the PATCH /api/projects/:slug request body.
1033	 *
1034	 * Accepts `title`, `slug`, or both — but requires at least one field to be
1035	 * present. Hoisted to module level so it can be reused and inspected in tests.
1036	 */
1037	export const RenameBodySchema = z
1038	  .object({
1039	    title: z.string().min(1).max(200).optional(),
1040	    slug: z.string().min(1).max(200).optional(),
1041	  })
1042	  .refine((d) => d.title !== undefined || d.slug !== undefined, {
1043	    message: 'At least one of title or slug must be provided.',
1044	  });
1045	
1046	/**
1047	 * Handles `PATCH /api/projects/:slug`.
1048	 *
1049	 * Accepts a partial update body with `title`, `slug`, or both:
1050	 * - `title` — persists a new display title via `LedgerStore.updateTitle()`.
1051	 * - `slug`  — renames the ledger storage directory and updates `.meta.json`
1052	 *             via `LedgerStore.renameSlug()`. The response `ProjectMeta.slug`
1053	 *             reflects the new slug so the frontend can redirect.
1054	 *
1055	 * Operations are applied in order: title first, then slug. Each updates
1056	 * `latestMeta` independently. `last_updated` is **not** modified by either
1057	 * operation — renaming is cosmetic and must not distort sort order.
1058	 *
1059	 * Do not reuse the `LedgerStore` instance after a slug rename; its internal
1060	 * `storageDir` points to the (now non-existent) old path.
1061	 *
1062	 * Throws `NOT_FOUND` if the project does not exist.
1063	 * Throws `VALIDATION_ERROR` if the body is empty or fails schema validation.
1064	 * Throws `CONFLICT` if the target slug directory already exists.
1065	 * @param repoName  Optional repository name used to resolve the namespaced storage path.
1066	 */
1067	export async function handleRenameProject(
1068	  ledgerRoot: string,
1069	  slug: string,
1070	  body: unknown,
1071	  repoName?: string
1072	): Promise<ProjectMeta> {
1073	  assertSafeSlug(slug);
1074	  const parseResult = RenameBodySchema.safeParse(body);
1075	  if (!parseResult.success) {
1076	    validationError('Invalid rename request body.', parseResult.error.issues);
1077	  }
1078	  const { title, slug: newSlug } = parseResult.data;
1079	
1080	  // Early-reject invalid slug patterns before touching disk.
1081	  if (newSlug !== undefined && !assertSafeSegment(newSlug)) {
1082	    validationError(
1083	      `Invalid slug '${newSlug}'. Must match ^[a-z0-9][a-z0-9-]*$.`
1084	    );
1085	  }
1086	
1087	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
1088	
1089	  let latestMeta: ProjectMeta | undefined;
1090	
1091	  if (title !== undefined) {
1092	    latestMeta = await store.updateTitle(title);
1093	  }
1094	
1095	  if (newSlug !== undefined) {
1096	    if (newSlug === slug) {
1097	      // Same-slug no-op: nothing to rename. Materialise latestMeta if needed.
1098	      latestMeta ??= await store.readProjectMeta();
1099	    } else {

1100	      try {
1101	        latestMeta = await store.renameSlug(newSlug);
1102	      } catch (err: unknown) {
1103	        if (err instanceof SlugConflictError) {
1104	          conflict(`Slug already in use: '${newSlug}'.`);
1105	        }
1106	        throw err;
1107	      }
1108	    }
1109	  }
1110	
1111	  // latestMeta is always defined here: the .refine() above guarantees at least
1112	  // one branch ran. The non-null assertion keeps TypeScript happy.
1113	  return latestMeta!;
1114	}
