1186	export interface WpOverviewEntry {
1187	  work_package_id: string;
1188	  status: WorkPackageStatus;
1189	  assigned_to: string | null;
1190	  dependencies: string[];
1191	  pipeline_stages: WpPipelineStage[];
1192	  acceptance_criteria: { met: number; total: number };
1193	  blocked_by?: { type: string; description: string };
1194	}
1195	
1196	/**
1197	 * Returns an enriched summary array for every work package in the project.
1198	 *
1199	 * For each WP the handler resolves:
1200	 *  - pipeline_stages: ordered per CANONICAL_PIPELINE_ORDERING, with status
1201	 *    derived from the most recent pipeline entry of each stage type
1202	 *  - acceptance_criteria: met/total counts
1203	 *  - blocked_by: propagated from the WP detail when present
1204	 *
1205	 * Corrupt or missing WP detail files are skipped (same error-tolerance
1206	 * pattern as handleGetProjectHealth).
1207	 * STDIO discipline: this handler never writes to process.stdout.
1208	 * @param repoName  Optional repository name used to resolve the namespaced storage path.
1209	 */
1210	export async function handleGetWorkPackageOverview(
1211	  ledgerRoot: string,
1212	  slug: string,
1213	  repoName?: string
1214	): Promise<WpOverviewEntry[]> {
1215	  assertSafeSlug(slug);
1216	
1217	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
1218	
1219	  let rootIndex: RootIndex;
1220	  try {
1221	    rootIndex = await store.readRootIndex();
1222	  } catch (err) {
1223	    notFound(`Project '${slug}' not found or corrupted: ${String(err)}`);
1224	  }
1225	
1226	  const entries: WpOverviewEntry[] = (
1227	    await Promise.all(
1228	      rootIndex.work_packages.map(async (wpSummary) => {
1229	        let wp: WorkPackageDetail;
1230	        try {
1231	          wp = await store.readWorkPackage(wpSummary.work_package_id);
1232	        } catch (err) {
1233	          process.stderr.write(
1234	            `[handleGetWorkPackageOverview] Skipping WP "${wpSummary.work_package_id}": ${String(err)}\n`
1235	          );
1236	          return null;
1237	        }
1238	
1239	        // Resolve active stages, filtering through CANONICAL_PIPELINE_ORDERING
1240	        // to guarantee the output is always in canonical execution order.
1241	        const rawStages: string[] = wp.active_pipeline_stages ?? [...DEFAULT_PIPELINE_STAGES];
1242	        const orderedStages = CANONICAL_PIPELINE_ORDERING.filter((s) => rawStages.includes(s));
1243	
1244	        // Build a lookup map from stage type → latest pipeline entry.
1245	        // Iterating in array order means later entries for the same type overwrite
1246	        // earlier ones, so the map always holds the most recent execution.
1247	        const latestByType = new Map<string, WorkPackageDetail['pipelines'][number]>();
1248	        for (const pipeline of wp.pipelines) {
1249	          latestByType.set(pipeline.type, pipeline);
1250	        }
1251	
1252	        const pipeline_stages: WpPipelineStage[] = orderedStages.map((type) => {
1253	          const latest = latestByType.get(type);
1254	          let status: WpPipelineStage['status'] = 'pending';
1255	          if (latest) {
1256	            if (latest.status === 'IN_PROGRESS') status = 'in-progress';
1257	            else if (latest.status === 'PASS') status = 'pass';
1258	            else if (latest.status === 'FAIL') status = 'fail';
1259	          }
1260	          const rework_count =
1261	            (wp.rework_counts as Record<string, number> | undefined)?.[type] ?? 0;
1262	          return {
1263	            type,
1264	            agent: PIPELINE_AGENT_MAP[type],
1265	            status,
1266	            rework_count,
1267	          };
1268	        });
1269	
1270	        const metCount = wp.acceptance_criteria.filter((ac) => ac.met).length;
1271	        const entry: WpOverviewEntry = {
1272	          work_package_id: wp.work_package_id,
1273	          status: wp.status,
1274	          assigned_to: wp.assigned_to,
1275	          dependencies: wp.dependencies,
1276	          pipeline_stages,
1277	          acceptance_criteria: { met: metCount, total: wp.acceptance_criteria.length },
1278	        };
1279	
1280	        if (wp.blocked_by) {
1281	          entry.blocked_by = {
1282	            type: wp.blocked_by.type,
1283	            description: wp.blocked_by.description,
1284	          };
1285	        }
1286	
1287	        return entry;
1288	      })
1289	    )
1290	  ).filter((entry): entry is WpOverviewEntry => entry !== null);
1291	
1292	  return entries;
1293	}
