1660	/** Raw query parameters accepted by GET /api/knowledge. */
1661	export interface KnowledgeListParams {
1662	  scope?: string;
1663	  category?: string;
1664	  /** Comma-separated list of tags to filter by. */
1665	  tags?: string;
1666	  project_slug?: string;
1667	  /** Full-text search query — delegates to searchInsights when present. */
1668	  query?: string;
1669	  limit?: number | string;
1670	  offset?: number | string;
1671	}
1672	
1673	/**
1674	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
1675	 *
1676	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
1677	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
1678	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
1679	 *   treated as "no scope filter" rather than causing an error.
1680	 * - `tags` is a comma-separated string that is split before being forwarded.
1681	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
1682	 *   are silently ignored (limit → undefined, offset → 0).
1683	 *
1684	 * @note When `query` is present, `limit`, `offset`, and `tags` are **not forwarded** to
1685	 *   `searchInsights()` — that method does not support pagination or tag filtering.
1686	 *   Callers that need to combine full-text search with tag filtering should post-process
1687	 *   the returned array. This constraint will be re-evaluated in WP-004/WP-005.
1688	 */
1689	export async function handleListKnowledge(
1690	  ledgerRoot: string,
1691	  params: KnowledgeListParams = {}
1692	): Promise<Insight[]> {
1693	  const manager = new KnowledgeStoreManager(ledgerRoot);
1694	
1695	  // Validate scope — unrecognised values fall back to undefined (no filter).
1696	  const scopeResult = InsightScope.safeParse(params.scope);

1696	  const scopeResult = InsightScope.safeParse(params.scope);
1697	  const scope = scopeResult.success ? scopeResult.data : undefined;
1698	
1699	  const category = params.category ?? undefined;
1700	  const project_slug = params.project_slug ?? undefined;
1701	
1702	  // Split comma-separated tags; ignore empty segments.
1703	  const tags =
1704	    params.tags && params.tags.trim().length > 0
1705	      ? params.tags
1706	          .split(',')
1707	          .map((t) => t.trim())
1708	          .filter((t) => t.length > 0)
1709	      : undefined;
1710	
1711	  // Coerce pagination params.
1712	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
1713	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
1714	
1715	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
1716	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
1717	
1718	  if (params.query && params.query.trim().length > 0) {
1719	    return manager.searchInsights(params.query.trim(), { scope, project_slug, category });
1720	  }
1721	
1722	  return manager.listInsights({ scope, category, tags, project_slug, limit, offset });
1723	}
